using Microsoft.EntityFrameworkCore;
using OldSchoolLab.Data;
namespace OldSchoolLab.Services;

public static class WhatsAppCampaignSchema
{
    public static Task EnsureAsync(ApplicationDbContext db) => db.Database.ExecuteSqlRawAsync(Sql);
    public const string Sql = """
        CREATE TABLE IF NOT EXISTS "WhatsAppContacts" (
            "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            "CompanyId" integer NOT NULL, "Phone" varchar(15) NOT NULL,
            "ConsentStatus" varchar(20) NOT NULL DEFAULT 'Unknown',
            "ConsentExpiresAt" timestamp without time zone NULL,
            "ChangedAt" timestamp without time zone NOT NULL,
            "Evidence" varchar(500) NOT NULL, "ChangedByUserId" varchar(450) NOT NULL,
            "ChangedByUserName" varchar(120) NOT NULL);
        CREATE UNIQUE INDEX IF NOT EXISTS "IX_WhatsAppContacts_CompanyId_Phone" ON "WhatsAppContacts" ("CompanyId", "Phone");
        CREATE TABLE IF NOT EXISTS "WhatsAppConsentChanges" (
            "Id" uuid PRIMARY KEY, "CompanyId" integer NOT NULL, "RecordId" integer NOT NULL,
            "Phone" varchar(15) NOT NULL, "Status" varchar(20) NOT NULL,
            "ExpiresAt" timestamp without time zone NULL, "ChangedAt" timestamp without time zone NOT NULL,
            "Evidence" varchar(500) NOT NULL, "ActorId" varchar(450) NOT NULL, "ActorName" varchar(120) NOT NULL);
        CREATE INDEX IF NOT EXISTS "IX_WhatsAppConsentChanges_CompanyId_Phone_ChangedAt" ON "WhatsAppConsentChanges" ("CompanyId", "Phone", "ChangedAt");
        CREATE TABLE IF NOT EXISTS "WhatsAppMessageSettings" (
            "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "CompanyId" integer NOT NULL,
            "UserId" varchar(450) NOT NULL, "Message" varchar(2000) NOT NULL);
        CREATE UNIQUE INDEX IF NOT EXISTS "IX_WhatsAppMessageSettings_CompanyId_UserId" ON "WhatsAppMessageSettings" ("CompanyId", "UserId");
        CREATE TABLE IF NOT EXISTS "WhatsAppCampaigns" (
            "Id" uuid PRIMARY KEY, "CompanyId" integer NOT NULL,
            "UserId" varchar(450) NOT NULL, "UserName" varchar(120) NOT NULL,
            "Message" varchar(2000) NOT NULL, "Status" varchar(20) NOT NULL,
            "CreatedAt" timestamp without time zone NOT NULL);
        CREATE INDEX IF NOT EXISTS "IX_WhatsAppCampaigns_CompanyId_UserId_CreatedAt" ON "WhatsAppCampaigns" ("CompanyId", "UserId", "CreatedAt");
        CREATE TABLE IF NOT EXISTS "WhatsAppCampaignRecipients" (
            "Id" uuid PRIMARY KEY, "CampaignId" uuid NOT NULL REFERENCES "WhatsAppCampaigns"("Id") ON DELETE RESTRICT,
            "CompanyId" integer NOT NULL, "RecordId" integer NOT NULL, "Position" integer NOT NULL,
            "Phone" varchar(15) NOT NULL, "Name" varchar(120) NOT NULL, "Message" varchar(2000) NOT NULL,
            "Status" varchar(20) NOT NULL, "OpenedAt" timestamp without time zone NULL, "DeclaredSentAt" timestamp without time zone NULL,
            "UpdatedAt" timestamp without time zone NULL, "ActorId" varchar(450) NOT NULL,
            "ActorName" varchar(120) NOT NULL, "Reason" varchar(200) NOT NULL);
        CREATE UNIQUE INDEX IF NOT EXISTS "IX_WhatsAppCampaignRecipients_CampaignId_Phone" ON "WhatsAppCampaignRecipients" ("CampaignId", "Phone");
        CREATE INDEX IF NOT EXISTS "IX_WhatsAppCampaignRecipients_CompanyId_Phone_Status_DeclaredSentAt" ON "WhatsAppCampaignRecipients" ("CompanyId", "Phone", "Status", "DeclaredSentAt");
        """;
}
